def hydrate_time(nanoseconds, tz=None):
    if tz is None:
        tz = time.tz
    try:
        if nanoseconds >= 86400000000000:
            raise ValueError("Nanoseconds value exceeds maximum")
        milliseconds = int(nanoseconds / 1e6)
        seconds = int(milliseconds / 1000)
        microseconds = (milliseconds % 1000) * 1000
        return time.Time(seconds=seconds, microseconds=microseconds, tzinfo=tz)
    except OverflowError:
        raise ValueError("Nanoseconds value is too large")
