def discard(self, n=-1, qid=-1, dehydration_hooks=None,
            hydration_hooks=None, **handlers):
    # Validate input parameters
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(qid, int) or qid < 0:
        raise ValueError("qid must be a non-negative integer")
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise ValueError("dehydration_hooks must be a dictionary mapping types to functions")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise ValueError("hydration_hooks must be a dictionary mapping types to functions")

    # Construct the Discard message
    message = Packstream(action=ABC.DISCARD)

    # Add query ID to the message, if specified
    if qid != -1:
        message.query_id = qid

    # Add the number of records to discard, if specified
    if n != -1:
        message.n = n

    # Add dehydration hooks to the message, if specified
    if dehydration_hooks is not None:
        for cls, fn in dehydration_hooks.items():
            message.add_dehydrator(cls, fn)

    # Add hydration hooks to the message, if specified
    if hydration_hooks is not None:
        for cls, fn in hydration_hooks.items():
            message.add_hydrator(cls, fn)

    # Add handler functions to the message, if specified
    if handlers is not None:
        for key, val in handlers.items():
            message.add_handler(key, val)

    # Dispatch the message to the server
    self.send(message)
