def lfu_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        def _wrapper(*args):
            try:
                result = cache[args]
            except KeyError:
                result = func(*args)
                cache[args] = result
                while len(cache) > maxsize:
                    cache.popitem()
