def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            if lock is not None:
                with lock:
                    if key in cache:
                        return cache[key]
                    else:
                        result = func(*args, **kwargs)
                        cache[key] = result
                        return result
            else:
                if key in cache:
                    return cache[key]
                else:
                    result = func(*args, **kwargs)
                    cache[key] = result
                    return result
        return wrapper
    return decorator

