def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    result = set()
    for cls in classes:
        if cls not in result:
            result.add(cls)
            for parent in cls.__bases__:
                if parent not in result:
                    result.add(parent)
    return [cls for cls in result]
