def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Check if the inventory is a dictionary
    if not isinstance(inventory, dict):
        raise ValueError("Invalid inventory: must be a dictionary")

    # Check if the 'type' key is present and its value is a string
    if 'type' not in inventory or not isinstance(inventory['type'], str):
        if extract_spec_version:
            raise ValueError("Invalid inventory: 'type' key missing or not a string")
        else:
            # Use the version given in self.spec_version
            spec_version = self.spec_version
    else:
        # Extract the specification version from the 'type' value
        try:
            spec_version = inventory['type'].split('.')[0]
        except Exception:
            raise ValueError("Invalid inventory: 'type' value not in expected format")

    # Check if the 'packages' key is present and its value is a list
    if 'packages' not in inventory or not isinstance(inventory['packages'], list):
        raise ValueError("Invalid inventory: 'packages' key missing or not a list")

    # Check if each package is a dictionary
    for package in inventory['packages']:
        if not isinstance(package, dict):
            raise ValueError("Invalid package: must be a dictionary")
        if 'name' not in package or not isinstance(package['name'], str):
            raise ValueError("Invalid package: 'name' key missing or not a string")
        if 'version' not in package or not isinstance(package['version'], str):
            raise ValueError("Invalid package: 'version' key missing or not a string")

    # Check if the 'dependencies' key is present and its value is a list
    if 'dependencies' not in inventory or not isinstance(inventory['dependencies'], list):
        raise ValueError("Invalid inventory: 'dependencies' key missing or not a list")

    # Check if each dependency is a dictionary
    for dependency in inventory['dependencies']:
        if not isinstance(dependency, dict):
            raise ValueError("Invalid dependency: must be a dictionary")
        if 'name' not in dependency or not isinstance(dependency['name'], str):
            raise ValueError("Invalid dependency: 'name' key missing or not a string")
        if 'version' not in dependency or not isinstance(dependency['version'], str):
            raise ValueError("Invalid dependency: 'version' key missing or not a string")

    return True
