def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files listed in
    the manifest are referenced.
    """

    # Check that fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("'fixity' must be a dictionary")

    # Check that fixity contains 'checksum' and 'manifest_files' keys
    if 'checksum' not in fixity or 'manifest_files' not in fixity:
        raise ValueError("'fixity' must contain 'checksum' and 'manifest_files' keys")

    # Check that 'checksum' is a list of strings
    if not isinstance(fixity['checksum'], list):
        raise ValueError("'checksum' must be a list of strings")

    for file_checksum in fixity['checksum']:
        # Check that each file checksum is a string
        if not isinstance(file_checksum, str):
            raise ValueError("File checksums must be strings")

        # Check that each file checksum is in the manifest
        if file_checksum not in manifest_files:
            raise ValueError(f"File checksum '{file_checksum}' not found in manifest")

    # Check that 'manifest_files' is a list of strings
    if not isinstance(fixity['manifest_files'], list):
        raise ValueError("'manifest_files' must be a list of strings")

    for manifest_file in fixity['manifest_files']:
        # Check that each manifest file is a string
        if not isinstance(manifest_file, str):
            raise ValueError("Manifest files must be strings")

        # Check that each manifest file is in the checksum list
        if manifest_file not in fixity['checksum']:
            raise ValueError(f"Manifest file '{manifest_file}' not found in checksum list")

    # If we reach this point, the fixity block is valid
    return True

