def _eval_file(prefix, filename, file_folder):
    file_path = f"{file_folder}/{prefix}.xml"
    with open(file_path, "r") as f:
        xml_root = ET.fromstring(f.read())
        file_type = xml_root.findtext(".//assetType")
        if file_type == "Asset":
            packages[prefix] = {
                "type": file_type,
                "file": file_path
            }
        elif file_type == "Rendition":
            parent_asset = xml_root.findtext(".//parentAsset")
            if parent_asset not in packages:
                _eval_file(parent_asset, file_folder)
            packages[prefix] = {
                "type": file_type,
                "file": file_path,
                "parent": parent_asset
            }
        else:
            raise ValueError(f"Invalid file type '{file_type}' in file {file_path}")
    return packages

