def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: A string or a list of strings containing the command(s) to call.
    :param args: A list of strings containing the arguments to pass to the command(s).
    :param cwd: The directory to run the command(s) in. If None, the current working directory will be used.
    :param verbose: If True, the output of the command(s) will be printed to the console.
    :param hide_stderr: If True, the error output of the command(s) will be hidden.
    :param env: A dictionary containing environment variables to set for the command(s).
    :return: The exit code of the command(s).
    """
    if isinstance(commands, str):
        commands = [commands]
    for command in commands:
        try:
            if verbose:
                print(f"Running command: {command}")
            if env is not None:
                os.environ.update(env)
            if cwd is not None:
                os.chdir(cwd)
            process = subprocess.Popen(command, shell=True, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            output, error = process.communicate()
            if error and not hide_stderr:
                print(error.decode("utf-8"), file=sys.stderr)
            if output:
                output = output.decode("utf-8")
                if verbose:
                    print(output)
                else:
                    return output
        except Exception as e:
            print(f"Error running command: {command}", file=sys.stderr)
            print(f"{e}", file=sys.stderr)
        finally:
            if process is not None:
                process.kill()
    return None

