def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    # Validate storage root hierarchy
    num_objects = 0
    good_objects = 0
    for object_path in self.path.iterdir():
        if not object_path.is_file():
            continue
        try:
            with open(object_path) as f:
                num_objects += 1
                if validate_objects and not self.validate_object(f.read()):
                    good_objects += 1
        except OSError:
            if show_warnings:
                print(f"Warning: {object_path} is not a valid file.")
            continue
    if check_digests:
        for object_path in self.path.iterdir():
            if not object_path.is_file():
                continue
            try:
                with open(object_path) as f:
                    checksum = self.calculate_checksum(f.read())
                    if checksum != self.digest_algorithm(object_path).hexlify():
                        if show_warnings:
                            print(f"Warning: {object_path} has an invalid checksum.")
                        continue
            except OSError:
                if show_warnings:
                    print(f"Warning: {object_path} is not a valid file.")
                continue
    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise ValueError("Version must be a string")

    if not re.match(r"^\d+\.\d+\.\d+$", version):
        raise ValueError("Version does not match expected pattern")

    major, minor, patch = version.split(".")
    if int(patch) == 9:
        if int(minor) == 9:
            if int(major) == 9:
                raise ValueError("Maximum version reached")
            else:
                return f"{int(major) + 1}.0.0"
        else:
            return f"{major}.{int(minor) + 1}.0"
    else:
        return f"{major}.{minor}.{int(patch) + 1}"

def deep_merge_nodes(nodes):
    result = {}
    for key, value in nodes:
        if key in result and isinstance(value, ruamel.yaml.nodes.MappingNode):
            result[key] = deep_merge_nodes(
                [(k, v) for k, v in result[key].value if k not in value.value]
                + [(k, v) for k, v in value.value]
            )
        else:
            result[key] = value
    return result

The above function can be called with a list of tuples containing the following:

* A `ruamel.yaml.nodes.ScalarNode` as the key, representing the name of the configuration section to merge.
* A `ruamel.yaml.nodes.MappingNode` or other `Node` as the value, representing the data to merge.

The function returns a new dict containing the merged data, with keys corresponding to the `ScalarNode` keys and values corresponding to the merged `Node` values. If there are colliding keys with non-`MappingNode` values (such as integers or strings), the last of the values wins.

For example, given the following input:
```
[
    (
        ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
        MappingNode(tag='tag:yaml.org,2002:map', value=[
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                ScalarNode(tag='tag:yaml.org,2002:int', value='24')
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                ScalarNode(tag='tag:yaml.org,2002:int', value='7')
            ),
        ]),
    ),
    (
        ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
        MappingNode(tag='tag:yaml.org,2002:map', value=[
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                ScalarNode(tag='tag:yaml.org,2002:int', value='5')
            ),
        ]),
    ),
]
```
