def was_processed(processed, path_name, verbose):
    if verbose:
        print(f"Checking if {path_name} has already been processed...")
    try:
        if os.path.isfile(path_name):
            full_path = os.path.abspath(path_name)
        elif os.path.isdir(path_name):
            full_path = os.path.abspath(os.path.join(path_name, os.curdir))
        else:
            raise ValueError(f"{path_name} is not a valid path")
        if full_path in processed:
            if verbose:
                print(f"{path_name} has already been processed")
            return True
        else:
            processed.add(full_path)
            return False
    except Exception as e:
        print(f"Error processing {path_name}: {str(e)}")
        return True

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of strings")
    if not all(isinstance(c, str) for c in alphabet):
        raise TypeError("alphabet must contain only strings")
    if not (padding is None or isinstance(padding, int)):
        raise TypeError("padding must be an integer or None")

    base = len(alphabet)
    result = ""
    is_negative = number < 0
    if is_negative:
        number = -number

    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    if is_negative:
        result = "-" + result

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str) or not isinstance(arg, str):
        raise TypeError("Both arguments must be strings")
    return value.replace(".", arg)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise TypeError("Input string must be a string")
    if not isinstance(alphabet, list):
        raise TypeError("Alphabet must be a list of strings")
    if len(alphabet) < 1 or len(alphabet) > 36:
        raise ValueError("Alphabet must contain at least 1 and at most 36 characters")
    if not all(isinstance(a, str) for a in alphabet):
        raise TypeError("Alphabet must consist of strings only")

    base = len(alphabet)
    result = 0
    for i, c in enumerate(reversed(string)):
        try:
            digit = alphabet.index(c)
        except ValueError:
            raise ValueError("Character {} not found in alphabet".format(c))
        result += digit * base ** i

    return result

