def run_command(commands: Union[list, str], args: Optional[list] = None, cwd: Optional[str] = None, verbose: bool = False, hide_stderr: bool = False, env: Optional[Dict[str, str]] = None) -> CompletedProcess:
    """Call the given command(s)."""
    if not isinstance(commands, str) and not isinstance(commands, list):
        raise TypeError("'commands' must be a string or a list of strings")
    if isinstance(commands, str):
        commands = [commands]
    if args and not isinstance(args, list):
        raise TypeError("'args' must be a list of strings if provided")
    if cwd and not isinstance(cwd, str):
        raise TypeError("'cwd' must be a string if provided")
    if not isinstance(verbose, bool):
        raise TypeError("'verbose' must be a bool")
    if not isinstance(hide_stderr, bool):
        raise TypeError("'hide_stderr' must be a bool")
    if env and not isinstance(env, dict):
        raise TypeError("'env' must be a dict of string keys and values if provided")

    try:
        _env = None
        if env:
            _env = {str(k): str(v) for k, v in env.items()}
        process = subprocess.Popen(commands, cwd=cwd, env=_env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, **kwargs)
        stdout, stderr = process.communicate()
        if not verbose:
            stdout = b''
        if hide_stderr:
            stderr = b''
    except OSError as e:
        return e.strerror
    return CompletedProcess(process.args, process.returncode, stdout, stderr)
