def find_roots(graph, prop, roots=None):
    if not isinstance(graph, rdflib.Graph):
        raise ValueError("Graph argument must be an rdflib.Graph object")
    if not isinstance(prop, rdflib.URIRef):
        raise ValueError("Prop argument must be an rdflib.URIRef object")
    if roots is not None and not isinstance(roots, set):
        raise ValueError("Roots argument must be a set object")

    if roots is None:
        roots = set()

    for s, p, o in graph.triples((None, prop, None)):
        if o not in roots:
            roots.add(o)
            find_roots(graph, prop, o, roots)

    return roots
