def load_configurations(config_filenames, overrides=None, resolve_env=True):
    if not isinstance(config_filenames, Sequence):
        raise TypeError(f"Invalid config_filenames: expected a sequence of strings, got {type(config_filenames)}")
    if overrides is not None and not isinstance(overrides, Sequence):
        raise TypeError(f"Invalid overrides: expected a mapping or None, got {type(overrides)}")
    if resolve_env is not None and not isinstance(resolve_env, bool):
        raise TypeError(f"Invalid resolve_env: expected a boolean or None, got {type(resolve_env)}")

    configs = {}
    errors = []

    for config_filename in config_filenames:
        if not isinstance(config_filename, str):
            errors.append(LogRecord(logging.CRITICAL, f"Invalid filename: {config_filename}", None))
            continue
        try:
            with open(config_filename, "r") as f:
                content = f.read()
        except OSError as e:
            errors.append(LogRecord(logging.CRITICAL, f"Error reading file {config_filename}: {e}", None))
            continue

        try:
            config = json.loads(content)
        except (TypeError, ValueError) as e:
            errors.append(LogRecord(logging.CRITICAL, f"Error parsing file {config_filename}: {e}", None))
            continue

        if overrides:
            for key, value in overrides.items():
                config[key] = value
        elif resolve_env:
            config = resolve_env_vars(config)

        if not config:
            errors.append(LogRecord(logging.WARNING, f"Empty config file {config_filename}", None))

        configs[config_filename] = config

    return configs, errors
