def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"{candidate} does not provide {iface}")

    # Check that all required methods and attributes are present
    for name in iface.names(getattr):
        if not hasattr(candidate, name):
            raise zope.interface.Invalid(f"{candidate} does not define {name}")

    # Check that all required methods have the correct signature
    for name, sig in iface.names(metaFunction):
        if hasattr(candidate, name):
            candidate_func = getattr(candidate, name)
            if not hasattr(candidate_func, "__call__"):
                raise zope.interface.Invalid(f"{candidate}.{name} is not a method")
            if not _signatures_match(sig, getfullargspec(candidate_func)):
                raise zope.interface.Invalid(f"{candidate}.{name} has the wrong signature")

    # Check that all required attributes have the correct type
    for name, meta in iface.names(metaAttribute):
        if hasattr(candidate, name):
            obj = getattr(candidate, name)
            if not isinstance(obj, meta.type):
                raise zope.interface.Invalid(f"{candidate}.{name} has the wrong type")

    return True

