def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    min_count = None
    min_item = None
    for key, (count, value) in self.items():
        if min_count is None or count < min_count:
            min_count = count
            min_item = (key, value)

    if min_item is None:
        raise KeyError("popitem(): dictionary is empty")

    del self[min_item[0]]
    return min_item[1]
