def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Split the text into words
    words = text.split()

    # Iterate over the words and check if they are links
    for i, word in enumerate(words):
        if word.startswith('http'):
            # Extract the link and add the appropriate attributes
            link = word
            link_attrs = {'target': '_blank', 'rel': 'nofollow'}

            # Replace the link with an <a> tag
            words[i] = f'<a href="{link}" {link_attrs}>{link}</a>'

    # Return the updated text
    return ' '.join(words)

