def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise ValueError("Tag must be a string")
    if len(tag) > 25:
        raise ValueError("Tag must not exceed 25 characters")
    if not tag.isalnum():
        raise ValueError("Tag must contain only letters and digits")
    if tag.startswith("_"):
        raise ValueError("Tag cannot start with an underscore")
    if tag.endswith("_"):
        raise ValueError("Tag cannot end with an underscore")
    if tag.startswith("-"):
        raise ValueError("Tag cannot start with a dash")
    if tag.endswith("-"):
        raise ValueError("Tag cannot end with a dash")
    if tag.isnumeric():
        raise ValueError("Tag cannot be numeric")
    if tag.lower() in RESERVED_WORDS:
        raise ValueError(f"Tag cannot be a reserved word: {RESERVED_WORDS}")
    return True

