def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}
    for arg in args:
        # Check if the arg is a control argument
        if arg.startswith("-"):
            # Strip the leading "-" from the arg
            control_args[arg[1:]] = args[arg]
        # Check if the arg is a nested argument
        elif arg.startswith("--"):
            # Strip the leading "--" from the arg
            nested_args[arg[2:]] = args[arg]
        # Check if the arg is a custom argument
        elif arg.startswith("-c"):
            # Strip the leading "-c" from the arg
            custom_args[arg[2:]] = args[arg]
    return control_args, nested_args, custom_args
```

def merge_extra_vars(vars_dict, extra_variables=None):
    if extra_variables is None:
        return vars_dict

    for key, value in extra_variables.items():
        if key not in vars_dict:
            vars_dict[key] = value
        elif isinstance(vars_dict[key], list):
            vars_dict[key].extend(value)
        else:
            vars_dict[key] = [vars_dict[key], value]

    return vars_dict

