def _convert_non_cli_args(self, parser_name: str, values_dict: dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    try:
        # Get the argument spec for the given command
        arg_spec = self.get_arg_spec(parser_name)
        # Iterate over the arguments and cast them to the correct type
        for arg_name, arg_value in values_dict.items():
            arg_type = arg_spec[arg_name]
            try:
                values_dict[arg_name] = arg_type(arg_value)
            except (ValueError, TypeError) as e:
                self.exception_handler(e, arg_name, parser_name)
    except Exception as e:
        self.exception_handler(e, parser_name)
```

